// Converte o payload Hyperflow em envelope Meta Cloud API,
// que é o formato que o Chatwoot já parseia nativamente via
// Whatsapp::IncomingMessageHyperflowService (herda do parser Cloud).
//
// AJUSTE_AQUI: os nomes exatos de campo do payload Hyperflow podem mudar.
// Ao receber a primeira mensagem real, abra o 'Executions' deste workflow
// e compare com os paths abaixo. Troque onde diferente.

const results = [];
for (const item of $input.all()) {
  const h = item.json;

  // Número Synapse OS (deve bater com Channel::Whatsapp#phone_number).
  const phoneNumber = h.to
    || h.phone
    || h.business_phone
    || h.channel?.phone_number
    || h.destination_phone_number;

  // Remetente.
  const from = h.from
    || h.sender?.phone
    || h.contact?.phone
    || h.wa_id;
  const name = h.sender?.name
    || h.contact?.name
    || h.profile?.name
    || '';

  // Tipo e conteúdo.
  const hyperflowType = h.type || h.message?.type || 'text';
  // Hyperflow usa 'file' pra documento; Meta Cloud usa 'document'.
  const typeMapBack = { file: 'document' };
  const metaType = typeMapBack[hyperflowType] || hyperflowType;

  const text = h.text
    || h.message?.text?.body
    || h.message?.text
    || h.payload?.text
    || '';
  const mediaUrl = h.media?.url
    || h.message?.media?.url
    || h.attachment?.url
    || h.payload?.url;
  const mediaId = h.media?.id
    || h.message?.media?.id
    || h.attachment?.id
    || '';
  const caption = h.message?.caption
    || h.caption
    || h.payload?.caption
    || '';

  const messageObj = {
    from: from,
    id: h.message_id || h.id || String(Date.now()),
    timestamp: String(Math.floor(new Date(h.timestamp || Date.now()).getTime() / 1000)),
    type: metaType
  };

  if (metaType === 'text') {
    messageObj.text = { body: text };
  } else if (['image', 'audio', 'video', 'document', 'sticker'].includes(metaType)) {
    messageObj[metaType] = {
      id: mediaId,
      url: mediaUrl,
      mime_type: h.media?.mime_type || h.message?.media?.mime_type || '',
      caption: caption
    };
  } else if (metaType === 'location') {
    messageObj.location = h.message?.location || h.payload || {};
  } else if (metaType === 'contact' || metaType === 'contacts') {
    messageObj.contacts = h.message?.contacts || h.payload?.contacts || [];
  } else {
    messageObj[metaType] = h.message || h.payload || {};
  }

  results.push({
    json: {
      _phone_number: phoneNumber,
      body: {
        object: 'whatsapp_business_account',
        entry: [{
          id: h.account_id || h.business_id || 'unknown',
          changes: [{
            field: 'messages',
            value: {
              messaging_product: 'whatsapp',
              metadata: {
                display_phone_number: phoneNumber,
                phone_number_id: phoneNumber
              },
              contacts: [{ wa_id: from, profile: { name: name } }],
              messages: [messageObj]
            }
          }]
        }]
      }
    }
  });
}
return results;
